-- Calculate total hours in the observation period
SELECT EXTRACT(EPOCH FROM (MAX(snapts) - MIN(snapts))) / 3600 as total_hours
FROM plant_record;

-- Verify join between operational_metrics and alert
SELECT COUNT(*) FROM operational_metrics om JOIN alert a ON om.snapops = a.snapalrt;
SELECT COUNT(*) FROM operational_metrics;

-- Try with ALL machines
SELECT ROUND(CAST(AVG(om.maintcost) AS numeric), 2) as avg_repair_cost
FROM operational_metrics om;

-- Try: AVG(maintcost / mttrh)
SELECT ROUND(CAST(AVG(om.maintcost::numeric / om.mttrh::numeric) AS numeric), 2) as avg_repair_cost
FROM operational_metrics om;

-- Check if replcost / 4 gives a reasonable answer
SELECT ROUND(CAST(AVG(om.replcost) AS numeric), 2) as avg_replcost
FROM operational_metrics om;

SELECT ROUND(CAST(AVG(om.maintcost) / AVG(CASE WHEN a.alrtcnt ~ '(\d+)' THEN SUBSTRING(a.alrtcnt FROM '(\d+)')::int ELSE 0 END) AS numeric), 2) as avg_repair_cost
FROM operational_metrics om
JOIN alert a ON om.snapops = a.snapalrt;

-- Check if snapops and snapalrt have the same set of values
SELECT COUNT(DISTINCT snapops) FROM operational_metrics;
SELECT COUNT(DISTINCT snapalrt) FROM alert;

SELECT ROUND(CAST(AVG(om.maintcost::numeric * om.mtbfh::numeric / 8760.0) AS numeric), 2) as avg_repair_cost
FROM operational_metrics om
WHERE om.mtbfh IS NOT NULL;
